CREATE OR REPLACE FUNCTION set_updated_at() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.updated_at := now(); RETURN NEW; END; $$;
CREATE TRIGGER trg_products_updated_at BEFORE UPDATE ON products FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE TRIGGER trg_orders_updated_at BEFORE UPDATE ON orders FOR EACH ROW EXECUTE FUNCTION set_updated_at();
CREATE OR REPLACE FUNCTION write_audit_log() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE v_tenant uuid; v_id uuid; BEGIN IF TG_OP='DELETE' THEN v_tenant:=OLD.tenant_id; v_id:=OLD.id; INSERT INTO audit_log(tenant_id,table_name,record_id,operation,changed_by,old_row) VALUES(v_tenant,TG_TABLE_NAME,v_id,TG_OP,current_setting('app.actor_id',true),to_jsonb(OLD)); RETURN OLD; ELSIF TG_OP='UPDATE' THEN v_tenant:=NEW.tenant_id; v_id:=NEW.id; INSERT INTO audit_log(tenant_id,table_name,record_id,operation,changed_by,old_row,new_row) VALUES(v_tenant,TG_TABLE_NAME,v_id,TG_OP,current_setting('app.actor_id',true),to_jsonb(OLD),to_jsonb(NEW)); RETURN NEW; ELSE v_tenant:=NEW.tenant_id; v_id:=NEW.id; INSERT INTO audit_log(tenant_id,table_name,record_id,operation,changed_by,new_row) VALUES(v_tenant,TG_TABLE_NAME,v_id,TG_OP,current_setting('app.actor_id',true),to_jsonb(NEW)); RETURN NEW; END IF; END; $$;
CREATE TRIGGER trg_products_audit AFTER INSERT OR UPDATE OR DELETE ON products FOR EACH ROW EXECUTE FUNCTION write_audit_log();
CREATE TRIGGER trg_orders_audit AFTER INSERT OR UPDATE OR DELETE ON orders FOR EACH ROW EXECUTE FUNCTION write_audit_log();
